import flask
from flask import request, jsonify, send_file
import subprocess
import os
import hashlib
import tempfile

app = flask.Flask(__name__)

DATADIR = '/opt/app/workspace'

@app.route('/api/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document using system pandoc installation."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    output_format = request.form.get('format', 'pdf')

    # Validate output format
    allowed_formats = ['pdf', 'html', 'docx', 'epub', 'rst']
    if output_format not in allowed_formats:
        return jsonify({'error': f'Format must be one of {allowed_formats}'}), 400

    # Save uploaded file
    file_hash = hashlib.md5(uploaded.read()).hexdigest()
    uploaded.seek(0)
    input_path = os.path.join(DATADIR, f'{file_hash}_input.md')
    output_path = os.path.join(DATADIR, f'{file_hash}_output.{output_format}')
    uploaded.save(input_path)

    # Build conversion command
    cmd = f'pandoc {input_path} -o {output_path} --resource-path={DATADIR}'

    # Allow user to pass extra pandoc flags for customization
    extra_args = request.form.get('pandoc_args', '')
    if extra_args:
        cmd = cmd + ' ' + extra_args

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=DATADIR
        )
        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        return send_file(output_path, as_attachment=True)
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup
        for p in [input_path, output_path]:
            try:
                os.unlink(p)
            except OSError:
                pass


@app.route('/api/templates', methods=['GET'])
def list_templates():
    """List available conversion templates."""
    template_dir = os.path.join(DATADIR, 'templates')
    if not os.path.isdir(template_dir):
        return jsonify({'templates': []})
    templates = os.listdir(template_dir)
    return jsonify({'templates': templates})


@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'pandoc': True})


if __name__ == '__main__':
    os.makedirs(DATADIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
